### `CheckoutPage.tsx`
```tsx
import React, { useMemo, useState } from 'react';
import './CheckoutPage.css';
import type { CheckoutPageProps, DeliveryAddress } from './types';

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  street: '',
  city: '',
  postalCode: '',
  country: '',
  phone: '',
};

type FormErrors = Partial<Record<keyof DeliveryAddress, string>>;

function validateAddress(address: DeliveryAddress): FormErrors {
  const errors: FormErrors = {};

  if (!address.fullName.trim()) errors.fullName = 'Full name is required.';
  if (!address.street.trim()) errors.street = 'Street address is required.';
  if (!address.city.trim()) errors.city = 'City is required.';
  if (!address.postalCode.trim()) {
    errors.postalCode = 'Postal code is required.';
  } else if (!/^[A-Za-z0-9\s-]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = 'Enter a valid postal code.';
  }
  if (!address.country.trim()) errors.country = 'Country is required.';
  if (!address.phone.trim()) {
    errors.phone = 'Phone number is required.';
  } else if (!/^[+\d][\d\s-]{6,}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number.';
  }

  return errors;
}

function formatPrice(value: number): string {
  return value.toLocaleString(undefined, {
    style: 'currency',
    currency: 'USD',
  });
}

export default function CheckoutPage({
  cartItems,
  onBackToCart,
  onPay,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<FormErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [isPaying, setIsPaying] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [cartItems]
  );
  const shipping = cartItems.length > 0 ? 4.99 : 0;
  const total = subtotal + shipping;

  const handleChange = (field: keyof DeliveryAddress) => (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    setAddress((prev) => ({ ...prev, [field]: e.target.value }));
  };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validateAddress(address));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      street: true,
      city: true,
      postalCode: true,
      country: true,
      phone: true,
    });

    if (Object.keys(validationErrors).length > 0) {
      return;
    }

    setPayError(null);
    setIsPaying(true);
    try {
      await onPay(address);
    } catch (err) {
      setPayError(
        err instanceof Error ? err.message : 'Payment failed. Please try again.'
      );
    } finally {
      setIsPaying(false);
    }
  };

  const isCartEmpty = cartItems.length === 0;

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button
          type="button"
          className="back-link"
          onClick={onBackToCart}
          aria-label="Back to cart"
        >
          ← Back to cart
        </button>
        <h1 className="checkout-title">Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="checkout-section cart-summary" aria-label="Order summary">
          <h2 className="section-title">Order summary</h2>

          {isCartEmpty ? (
            <p className="empty-cart">Your cart is empty.</p>
          ) : (
            <ul className="cart-list">
              {cartItems.map((item) => (
                <li key={item.id} className="cart-item">
                  <div className="cart-item-image-wrapper">
                    {item.imageUrl ? (
                      <img
                        src={item.imageUrl}
                        alt={item.name}
                        className="cart-item-image"
                      />
                    ) : (
                      <div className="cart-item-image-placeholder" aria-hidden="true" />
                    )}
                  </div>
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.price * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="totals">
            <div className="totals-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
            </div>
            <div className="totals-row">
              <span>Shipping</span>
              <span>{formatPrice(shipping)}</span>
            </div>
            <div className="totals-row totals-row-grand">
              <span>Total</span>
              <span>{formatPrice(total)}</span>
            </div>
          </div>
        </section>

        <section className="checkout-section address-form-section" aria-label="Delivery address">
          <h2 className="section-title">Delivery address</h2>

          <form className="address-form" onSubmit={handleSubmit} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                name="fullName"
                type="text"
                autoComplete="name"
                value={address.fullName}
                onChange={handleChange('fullName')}
                onBlur={handleBlur('fullName')}
                aria-invalid={Boolean(touched.fullName && errors.fullName)}
              />
              {touched.fullName && errors.fullName && (
                <span className="field-error">{errors.fullName}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                name="street"
                type="text"
                autoComplete="street-address"
                value={address.street}
                onChange={handleChange('street')}
                onBlur={handleBlur('street')}
                aria-invalid={Boolean(touched.street && errors.street)}
              />
              {touched.street && errors.street && (
                <span className="field-error">{errors.street}</span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  name="city"
                  type="text"
                  autoComplete="address-level2"
                  value={address.city}
                  onChange={handleChange('city')}
                  onBlur={handleBlur('city')}
                  aria-invalid={Boolean(touched.city && errors.city)}
                />
                {touched.city && errors.city && (
                  <span className="field-error">{errors.city}</span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  name="postalCode"
                  type="text"
                  autoComplete="postal-code"
                  value={address.postalCode}
                  onChange={handleChange('postalCode')}
                  onBlur={handleBlur('postalCode')}
                  aria-invalid={Boolean(touched.postalCode && errors.postalCode)}
                />
                {touched.postalCode && errors.postalCode && (
                  <span className="field-error">{errors.postalCode}</span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                name="country"
                type="text"
                autoComplete="country-name"
                value={address.country}
                onChange={handleChange('country')}
                onBlur={handleBlur('country')}
                aria-invalid={Boolean(touched.country && errors.country)}
              />
              {touched.country && errors.country && (
                <span className="field-error">{errors.country}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                name="phone"
                type="tel"
                autoComplete="tel"
                value={address.phone}
                onChange={handleChange('phone')}
                onBlur={handleBlur('phone')}
                aria-invalid={Boolean(touched.phone && errors.phone)}
              />
              {touched.phone && errors.phone && (
                <span className="field-error">{errors.phone}</span>
              )}
            </div>

            {payError && (
              <div className="pay-error" role="alert">
                {payError}
              </div>
            )}

            <div className="checkout-actions">
              <button
                type="button"
                className="secondary-button"
                onClick={onBackToCart}
                disabled={isPaying}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="primary-button"
                disabled={isCartEmpty || isPaying}
              >
                {isPaying ? 'Processing…' : `Pay ${formatPrice(total)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
```

