### Example usage
```tsx
import CheckoutPage from './CheckoutPage';
import type { CartItem, DeliveryAddress } from './types';

const sampleItems: CartItem[] = [
  { id: '1', name: 'Wireless Headphones', price: 79.99, quantity: 1 },
  { id: '2', name: 'USB-C Cable', price: 9.99, quantity: 2 },
];

function App() {
  const handleBackToCart = () => {
    // navigate back to the cart route
  };

  const handlePay = async (address: DeliveryAddress) => {
    // call your payment API, e.g. await api.pay({ address, items: sampleItems })
    console.log('Paying with address:', address);
  };

  return (
    <CheckoutPage
      cartItems={sampleItems}
      onBackToCart={handleBackToCart}
      onPay={handlePay}
    />
  );
}

export default App;
```

Notes:
- `onPay` is async-aware — the Pay button shows "Processing…" and disables itself while awaiting, and surfaces a `payError` message if it rejects.
- Address fields validate on blur and again on submit; the Pay button is disabled on an empty cart.
- Responsive: two-column layout above 768px, stacked below.
